#!/usr/bin/env node
// scaffold-search-filter-bar.js — v78 ship reusable search + filter
// primitives. Eliminates per-page debounce/URL-sync reinvention.
//
// Emits:
//   - app/hooks/useDebouncedValue.ts   generic debounce hook
//   - app/hooks/useUrlState.ts         get/set URL search params (RR7-safe)
//   - app/components/atoms/SearchInput.tsx   icon + debounced input
//   - app/components/atoms/FilterChips.tsx   toggleable chip group
//
// Idempotent. Marker: '// Generated by scaffold-search-filter-bar'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-search-filter-bar --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-search-filter-bar — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-search-filter-bar/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

var USE_DEBOUNCED_VALUE = [
  marker(),
  "import { useEffect, useState } from 'react';",
  '',
  'export function useDebouncedValue<T>(value: T, delayMs = 300): T {',
  '  const [debounced, setDebounced] = useState(value);',
  '  useEffect(() => {',
  '    const id = setTimeout(() => setDebounced(value), delayMs);',
  '    return () => clearTimeout(id);',
  '  }, [value, delayMs]);',
  '  return debounced;',
  '}',
  '',
].join('\n');

var USE_URL_STATE = [
  marker(),
  "import { useCallback, useMemo } from 'react';",
  "import { useSearchParams } from 'react-router';",
  '',
  '/**',
  ' * Bind a single URL search param. Returns [value, setValue].',
  ' * Setting to undefined / null removes the param.',
  ' */',
  'export function useUrlState<T extends string = string>(key: string, defaultValue?: T) {',
  '  const [params, setParams] = useSearchParams();',
  '  const value = useMemo<T | undefined>(() => (params.get(key) as T | null) ?? defaultValue, [params, key, defaultValue]);',
  '  const set = useCallback((next: T | undefined | null) => {',
  '    setParams((prev) => {',
  '      const merged = new URLSearchParams(prev);',
  '      if (next == null || next === \'\') merged.delete(key);',
  '      else merged.set(key, String(next));',
  '      return merged;',
  '    });',
  '  }, [key, setParams]);',
  '  return [value, set] as const;',
  '}',
  '',
].join('\n');

var SEARCH_INPUT = [
  marker(),
  "import { useEffect, useState } from 'react';",
  "import { Search } from 'lucide-react';",
  "import { Input } from '~/components/ui/input';",
  "import { useDebouncedValue } from '~/hooks/useDebouncedValue';",
  '',
  'export interface SearchInputProps {',
  '  value?: string;',
  '  placeholder?: string;',
  '  delayMs?: number;',
  '  onDebouncedChange: (value: string) => void;',
  '  testId?: string;',
  '}',
  '',
  "export function SearchInput({ value = '', placeholder = 'Search…', delayMs = 300, onDebouncedChange, testId = 'search-input' }: SearchInputProps) {",
  '  const [local, setLocal] = useState(value);',
  '  const debounced = useDebouncedValue(local, delayMs);',
  '  useEffect(() => { onDebouncedChange(debounced); }, [debounced, onDebouncedChange]);',
  '  return (',
  '    <div className="relative w-full max-w-sm">',
  '      <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />',
  '      <Input',
  '        value={local}',
  '        onChange={(e) => setLocal(e.target.value)}',
  '        placeholder={placeholder}',
  '        className="pl-8"',
  '        data-testid={testId}',
  '      />',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

var FILTER_CHIPS = [
  marker(),
  "import { cn } from '~/lib/utils';",
  "import { Button } from '~/components/ui/button';",
  '',
  'export interface FilterOption {',
  '  value: string;',
  '  label: string;',
  '}',
  '',
  'export interface FilterChipsProps {',
  '  options: FilterOption[];',
  '  selected?: string;',
  '  onChange: (value: string | undefined) => void;',
  '  testId?: string;',
  '}',
  '',
  "export function FilterChips({ options, selected, onChange, testId = 'filter-chips' }: FilterChipsProps) {",
  '  return (',
  '    <div className="flex flex-wrap gap-2" data-testid={testId}>',
  '      <Button',
  "        variant={selected ? 'outline' : 'default'}",
  "        size=\"sm\"",
  '        onClick={() => onChange(undefined)}',
  '        data-testid={`${testId}-all`}',
  '      >',
  "        All",
  '      </Button>',
  '      {options.map((o) => (',
  '        <Button',
  '          key={o.value}',
  "          variant={selected === o.value ? 'default' : 'outline'}",
  "          size=\"sm\"",
  '          onClick={() => onChange(o.value)}',
  "          className={cn(selected === o.value && 'shadow-sm')}",
  '          data-testid={`${testId}-${o.value}`}',
  '        >',
  '          {o.label}',
  '        </Button>',
  '      ))}',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var files = [
    { p: 'app/hooks/useDebouncedValue.ts', c: USE_DEBOUNCED_VALUE },
    { p: 'app/hooks/useUrlState.ts', c: USE_URL_STATE },
    { p: 'app/components/atoms/SearchInput.tsx', c: SEARCH_INPUT },
    { p: 'app/components/atoms/FilterChips.tsx', c: FILTER_CHIPS },
  ];
  var written = 0, skipped = 0;
  files.forEach(function (f) {
    var r = writeIfManaged(path.join(args.target, f.p), f.c, args.force, args.dryRun);
    if (r.written) written++; else skipped++;
    if (args.verbose) console.log('  ' + f.p + ': ' + (r.written ? 'wrote' : r.reason));
  });
  console.log('scaffold-search-filter-bar: ' + written + ' written, ' + skipped + ' skipped');
}

main();
